/** One tool's mark, by its label. */
export function toolMark(label: string) {
	const tool = [...tools, ...platforms].find((candidate) => candidate.label === label);
	if (!tool) throw new Error(`No mark for ${label}`);
	return tool;
}

/**
 * A mark's SVG body with its gradient and mask ids made unique. The same mark
 * can appear several times on a page, and some copies sit in a layout that is
 * hidden at this width: a `url(#id)` that resolves to a hidden copy paints
 * nothing.
 */
export function markBody(mark: ToolMark, suffix: string) {
	return mark.body.replace(/(id='|url\(#|href='#)([\w-]+)/g, `$1$2-${suffix}`);
}
